Here is the commit message:
Bluetooth: btmtk: validate WMT event SKB length before struct
 access

btmtk_usb_hci_wmt_sync() casts the WMT event response SKB data to
struct btmtk_hci_wmt_evt (7 bytes) and struct btmtk_hci_wmt_evt_funcc
(9 bytes) without first checking that the SKB contains enough data.
A short firmware response causes out-of-bounds reads from SKB tailroom.

Use skb_pull_data() to validate and advance past the base WMT event
header. For the FUNC_CTRL case, pull the additional status field bytes
before accessing them.

Fixes: d019930b0049 ("Bluetooth: btmtk: move btusb_mtk_hci_wmt_sync to btmtk.c")
Cc: stable@vger.kernel.org
Signed-off-by: Tristan Madani <tristan@talencesecurity.com>
Signed-off-by: Luiz Augusto von Dentz <luiz.von.dentz@intel.com>

Here is the root cause:
The function btmtk_usb_hci_wmt_sync() directly casts the SKB data pointer to struct types (btmtk_hci_wmt_evt and btmtk_hci_wmt_evt_funcc) without verifying that the SKB contains sufficient data. A short firmware response leads to out-of-bounds reads from SKB tailroom.

Here is the patch:

 static int btmtk_usb_hci_wmt_sync(struct hci_dev *hdev,
 				  struct btmtk_hci_wmt_params *wmt_params)
 {
 	struct btmtk_data *data = hci_get_priv(hdev);
 	struct btmtk_hci_wmt_evt_funcc *wmt_evt_funcc;
 	u32 hlen, status = BTMTK_WMT_INVALID;
 	struct btmtk_hci_wmt_evt *wmt_evt;
 	struct btmtk_hci_wmt_cmd *wc;
 	struct btmtk_wmt_hdr *hdr;
 	int err;

 	/* Send the WMT command and wait until the WMT event returns */
 	hlen = sizeof(*hdr) + wmt_params->dlen;
 	if (hlen > 255)
 		return -EINVAL;

 	wc = kzalloc(hlen, GFP_KERNEL);
 	if (!wc)
 		return -ENOMEM;

 	hdr = &wc->hdr;
 	hdr->dir = 1;
 	hdr->op = wmt_params->op;
 	hdr->dlen = cpu_to_le16(wmt_params->dlen + 1);
 	hdr->flag = wmt_params->flag;
 	memcpy(wc->data, wmt_params->data, wmt_params->dlen);

 	set_bit(BTMTK_TX_WAIT_VND_EVT, &data->flags);

 	/* WMT cmd/event doesn't follow up the generic HCI cmd/event handling,
 	 * it needs constantly polling control pipe until the host received the
 	 * WMT event, thus, we should require to specifically acquire PM counter
 	 * on the USB to prevent the interface from entering auto suspended
 	 * while WMT cmd/event in progress.
 	 */
 	err = usb_autopm_get_interface(data->intf);
 	if (err < 0)
 		goto err_free_wc;

 	err = __hci_cmd_send(hdev, 0xfc6f, hlen, wc);

 	if (err < 0) {
 		clear_bit(BTMTK_TX_WAIT_VND_EVT, &data->flags);
 		usb_autopm_put_interface(data->intf);
 		goto err_free_wc;
 	}

 	/* Submit control IN URB on demand to process the WMT event */
 	err = btmtk_usb_submit_wmt_recv_urb(hdev);

 	usb_autopm_put_interface(data->intf);

 	if (err < 0)
 		goto err_free_wc;

 	/* The vendor specific WMT commands are all answered by a vendor
 	 * specific event and will have the Command Status or Command
 	 * Complete as with usual HCI command flow control.
 	 *
 	 * After sending the command, wait for BTUSB_TX_WAIT_VND_EVT
 	 * state to be cleared. The driver specific event receive routine
 	 * will clear that state and with that indicate completion of the
 	 * WMT command.
 	 */
 	err = wait_on_bit_timeout(&data->flags, BTMTK_TX_WAIT_VND_EVT,
 				  TASK_UNINTERRUPTIBLE, HCI_INIT_TIMEOUT);

 	if (err) {
 		bt_dev_err(hdev, "Execution of wmt command timed out");
 		clear_bit(BTMTK_TX_WAIT_VND_EVT, &data->flags);
 		err = -ETIMEDOUT;
 		goto err_free_wc;
 	}

 	if (data->evt_skb == NULL)
 		goto err_free_wc;

-	/* Parse and handle the return WMT event */
-	wmt_evt = (struct btmtk_hci_wmt_evt *)data->evt_skb->data;
+	wmt_evt = skb_pull_data(data->evt_skb, sizeof(*wmt_evt));
+	if (!wmt_evt) {
+		bt_dev_err(hdev, "WMT event too short (%u bytes)",
+			   data->evt_skb->len);
+		err = -EINVAL;
+		goto err_free_skb;
+	}
 	if (wmt_evt->whdr.op != hdr->op) {
 		bt_dev_err(hdev, "Wrong op received %d expected %d",
 			   wmt_evt->whdr.op, hdr->op);
 		err = -EIO;
 		goto err_free_skb;
 	}

 	switch (wmt_evt->whdr.op) {
 	case BTMTK_WMT_SEMAPHORE:
 		if (wmt_evt->whdr.flag == 2)
 			status = BTMTK_WMT_PATCH_UNDONE;
 		else
 			status = BTMTK_WMT_PATCH_DONE;
 		break;
 	case BTMTK_WMT_FUNC_CTRL:
+		if (!skb_pull_data(data->evt_skb,
+				   sizeof(wmt_evt_funcc->status))) {
+			err = -EINVAL;
+			goto err_free_skb;
+		}
+
 		wmt_evt_funcc = (struct btmtk_hci_wmt_evt_funcc *)wmt_evt;
 		if (be16_to_cpu(wmt_evt_funcc->status) == 0x404)
 			status = BTMTK_WMT_ON_DONE;
 		else if (be16_to_cpu(wmt_evt_funcc->status) == 0x420)
 			status = BTMTK_WMT_ON_PROGRESS;
 		else
 			status = BTMTK_WMT_ON_UNDONE;
 		break;
 	case BTMTK_WMT_PATCH_DWNLD:
 		if (wmt_evt->whdr.flag == 2)
 			status = BTMTK_WMT_PATCH_DONE;
 		else if (wmt_evt->whdr.flag == 1)
 			status = BTMTK_WMT_PATCH_PROGRESS;
 		else
 			status = BTMTK_WMT_PATCH_UNDONE;
 		break;
 	}

 	if (wmt_params->status)
 		*wmt_params->status = status;

 err_free_skb:
 	kfree_skb(data->evt_skb);
 	data->evt_skb = NULL;
 err_free_wc:
 	kfree(wc);
 	return err;
 }



